/**
 * Generates simple/js/data/constituencies.js
 *
 * Source: tools/acs.json — the 117 Punjab Legislative Assembly constituencies,
 * verified against the Wikipedia list of Punjab Legislative Assembly
 * constituencies and the district-wise listing on punjabdata.com, with the
 * six that disagreed checked individually (Sri Hargobindpur, Baba Bakala,
 * Phagwara, Garhshankar, Balachaur, Amargarh).
 *
 * Real reference data only. No political values of any kind live in the
 * generated file — the game fills those in at runtime.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const acs = JSON.parse(fs.readFileSync(path.join(HERE, 'acs.json'), 'utf8'));

const constituencies = acs.map((row) => ({
  number: row[0],
  name: row[1],
  district: row[2],
  reserved: row[3] === 'SC' ? 'SC' : null,
}));

const districts = [];
for (const c of constituencies) {
  if (districts.indexOf(c.district) === -1) districts.push(c.district);
}
districts.sort();

const body = `/**
 * The 117 Punjab Legislative Assembly constituencies.
 * GENERATED by tools/build-simple-data.mjs — do not edit by hand.
 *
 * Real reference data: constituency number, name, district and SC reservation.
 * Verified against public sources (see the generator for details).
 *
 * Each record is deliberately open for the fields Version 2 will add:
 *   status          — who currently holds the seat
 *   playerSupport   — the player's projected vote share
 *   opponentSupport — projected vote share per rival party
 *   result          — the declared winner once the election is run
 * CONSTITUENCY_TEMPLATE below documents that shape in one place.
 */
window.CMP = window.CMP || {};

CMP.CONSTITUENCIES = ${JSON.stringify(constituencies, null, 0)};

CMP.DISTRICTS = ${JSON.stringify(districts, null, 0)};

CMP.TOTAL_SEATS = CMP.CONSTITUENCIES.length;

CMP.MAJORITY = Math.floor(CMP.TOTAL_SEATS / 2) + 1;

/** The per-constituency shape the game fills in. Version 1 leaves these empty. */
CMP.CONSTITUENCY_TEMPLATE = {
  status: null,
  playerSupport: null,
  opponentSupport: null,
  result: null,
};
`;

const out = path.join(HERE, '..', 'simple', 'js', 'data', 'constituencies.js');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, body);

console.log('constituencies: ' + constituencies.length);
console.log('districts: ' + districts.length);
console.log('SC reserved: ' + constituencies.filter((c) => c.reserved).length);
console.log('majority: ' + (Math.floor(constituencies.length / 2) + 1));
console.log('written: ' + path.relative(path.join(HERE, '..'), out));
